public struct NoteCreateArgs: Codable, Hashable, Sendable {
    public var space: SpaceRef?
    /// A folder to file it in; null or left out for Drafts.
    public var folderId: Patch<String>
    /// Makes it a page inside another note.
    public var parentId: Patch<String>
    public var title: String?
    /// A template: `builtin:<key>` or a template note's id.
    public var templateId: Patch<String>
    /// Open it in the note page straight away (default false: native opens it with the zoom).
    public var `open`: Bool?
    /// Revision 8 (R8.5): a note made from text (Services, Shortcuts, "New note with text"): the first line becomes the
    /// title (unless it's a long paragraph) and the rest the body, each line a paragraph. `title` and `templateId`
    /// are ignored then.
    public var text: String?

    enum CodingKeys: String, CodingKey {
        case space
        case folderId
        case parentId
        case title
        case templateId
        case `open`
        case text
    }

    public init(space: SpaceRef? = nil, folderId: String? = nil, parentId: String? = nil, title: String? = nil, templateId: String? = nil, open: Bool? = nil, text: String? = nil) {
        self.space = space
        self.folderId = Patch(folderId)
        self.parentId = Patch(parentId)
        self.title = title
        self.templateId = Patch(templateId)
        self.open = `open`
        self.text = text
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encodeIfPresent(self.space, forKey: .space)
        try container.encodePatch(self.folderId, forKey: .folderId)
        try container.encodePatch(self.parentId, forKey: .parentId)
        try container.encodeIfPresent(self.title, forKey: .title)
        try container.encodePatch(self.templateId, forKey: .templateId)
        try container.encodeIfPresent(self.open, forKey: .`open`)
        try container.encodeIfPresent(self.text, forKey: .text)
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.space = try container.decodeIfPresent(SpaceRef.self, forKey: .space)
        self.folderId = try container.decodePatch(String.self, forKey: .folderId)
        self.parentId = try container.decodePatch(String.self, forKey: .parentId)
        self.title = try container.decodeIfPresent(String.self, forKey: .title)
        self.templateId = try container.decodePatch(String.self, forKey: .templateId)
        self.open = try container.decodeIfPresent(Bool.self, forKey: .`open`)
        self.text = try container.decodeIfPresent(String.self, forKey: .text)
    }
}

